package main

import (
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/bazelbuild/rules_go/go/runfiles"
)

type PackageMetadata struct {
	Attributes map[string]string `json:"attributes"`
	Label      string            `json:"label"`
	Purl       string            `json:"purl"`
}

type License struct {
	Kind struct {
		Identifier string `json:"identifier"`
	} `json:"kind"`
	Text string `json:"text"`
}

// The purl of the `package_metadata` generated by `helm_import_repository`
// for each imported chart, keyed by a fragment of the repository name.
var expectedPurls = map[string]string{
	// `repository` imports resolve to the chart url in the repository's
	// `index.yaml`, which for bitnami is an `oci://` url.
	"with_external_deps_redis":         "pkg:oci/redis?repository_url=registry-1.docker.io%2Fbitnamicharts%2Fredis&tag=21.2.5",
	"with_external_deps_trust_manager": "pkg:generic/trust-manager@v0.24.0?checksum=sha256:0de4bbef2d1a013bd4a91c6f59a9cb0273dda9a785e018a9a16e8f2b096af823&download_url=https:%2F%2Fcharts.jetstack.io%2Fcharts%2Ftrust-manager-v0.24.0.tgz",
	// `url` imports.
	"with_external_deps_postgresql":   "pkg:generic/postgresql@14.0.5?checksum=sha256:38d9b6657aa3b0cc16d190570dbaf96796e997d03a1665264dac9966343e4d1b&download_url=https:%2F%2Fcharts.bitnami.com%2Fbitnami%2Fpostgresql-14.0.5.tgz",
	"with_external_deps_vault":        "pkg:generic/vault@0.31.0?checksum=sha256:fe80fae6a8838c75da9fbde1398f2c10bb4b5c31c425e559507ba99373297de2&download_url=https:%2F%2Fhelm.releases.hashicorp.com%2Fvault-0.31.0.tgz",
	"with_external_deps_grafana":      "pkg:oci/grafana?repository_url=registry-1.docker.io%2Fbitnamicharts%2Fgrafana&tag=12.1.4",
	"with_external_deps_bank_vaults":  "pkg:oci/vault-operator?repository_url=ghcr.io%2Fbank-vaults%2Fhelm-charts%2Fvault-operator&tag=1.23.0",
	"with_external_deps_karpenter":    "pkg:oci/karpenter?repository_url=public.ecr.aws%2Fkarpenter%2Fkarpenter&tag=1.9.0",
	"with_external_deps_cert_manager": "pkg:oci/cert-manager?repository_url=quay.io%2Fjetstack%2Fcharts%2Fcert-manager&tag=1.19.4",
}

// The SPDX identifier of the `license` generated for each chart.
var expectedLicenses = map[string]string{
	// From the `licenses` annotation.
	"with_external_deps_redis":      "Apache-2.0",
	"with_external_deps_postgresql": "Apache-2.0",
	"with_external_deps_grafana":    "Apache-2.0",
	// From the `artifacthub.io/license` annotation.
	"with_external_deps_trust_manager": "Apache-2.0",
	"with_external_deps_cert_manager":  "Apache-2.0",
	// From the `LICENSE` file shipped in the chart.
	"with_external_deps_vault": "MPL-2.0",
	// Neither annotated in `Chart.yaml` nor shipping a license file.
	"with_external_deps_karpenter":   "NOASSERTION",
	"with_external_deps_bank_vaults": "NOASSERTION",
}

const licenseAttribute = "build.bazel.attribute.license"

func chartOf(t *testing.T, rlocationpath string, charts map[string]string) string {
	for name := range charts {
		if strings.Contains(rlocationpath, name) {
			return name
		}
	}
	t.Errorf("Unexpected runfile %s", rlocationpath)
	return ""
}

func readJson(t *testing.T, rlocationpath string, value any) {
	path, err := runfiles.Rlocation(rlocationpath)
	if err != nil {
		t.Fatalf("Failed to find runfile %s: %v", rlocationpath, err)
	}
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("Failed to read %s: %v", path, err)
	}
	if err := json.Unmarshal(content, value); err != nil {
		t.Fatalf("Failed to parse %s: %v", path, err)
	}
}

func TestImportedChartPackageMetadata(t *testing.T) {
	rlocationpaths := os.Getenv("PACKAGE_METADATA")
	if rlocationpaths == "" {
		t.Fatal("PACKAGE_METADATA environment variable is not set")
	}

	found := map[string]bool{}
	for _, rlocationpath := range strings.Fields(rlocationpaths) {
		name := chartOf(t, rlocationpath, expectedPurls)
		if name == "" {
			continue
		}
		found[name] = true

		var metadata PackageMetadata
		readJson(t, rlocationpath, &metadata)

		if metadata.Purl != expectedPurls[name] {
			t.Errorf("Unexpected purl for %s.\nExpected: %s\nFound:    %s", name, expectedPurls[name], metadata.Purl)
		}

		if _, licensed := metadata.Attributes[licenseAttribute]; !licensed {
			t.Errorf("Expected %s to have a license attribute. Found attributes: %v", name, metadata.Attributes)
		}
	}

	for name := range expectedPurls {
		if !found[name] {
			t.Errorf("No package metadata found for %s", name)
		}
	}
}

func TestImportedChartLicenses(t *testing.T) {
	rlocationpaths := os.Getenv("LICENSES")
	if rlocationpaths == "" {
		t.Fatal("LICENSES environment variable is not set")
	}

	found := map[string]bool{}
	for _, rlocationpath := range strings.Fields(rlocationpaths) {
		name := chartOf(t, rlocationpath, expectedLicenses)
		if name == "" {
			continue
		}
		found[name] = true

		var license License
		readJson(t, rlocationpath, &license)

		if license.Kind.Identifier != expectedLicenses[name] {
			t.Errorf("Unexpected license for %s. Expected: %s, Found: %s", name, expectedLicenses[name], license.Kind.Identifier)
		}

		// Only vault ships its license text.
		hasText := strings.HasSuffix(license.Text, "/LICENSE")
		if expectText := name == "with_external_deps_vault"; hasText != expectText {
			t.Errorf("Expected %s to have a license text: %v. Found: %q", name, expectText, license.Text)
		}
	}

	for name := range expectedLicenses {
		if !found[name] {
			t.Errorf("No license found for %s", name)
		}
	}
}
